import React, { useState, useEffect } from 'react';
import { useContexState } from '../hooks/context';

import api from '../services/api'

interface ConvertListParam {
    data: {
        id: number;
        number: number;
        name: string;
        phone: string;
        price: number;
    }[]
};

interface ConvertListReturn {
    [key: string]: [{
        id: number;
        name: string;
        phone: string;
        price: number;
    }]
};

interface NumbersType {
    lineCards: number;
    id: string;
};

export function useLoadPage() {
    const [getList, setGetList] = useState<ConvertListReturn>();
    const [loading, setLoading] = useState(true)

    const {
        feed,
    } = useContexState();

    const {
        setFeed,
    } = useContexState();

    function convertList({ data }: ConvertListParam) {
        return data.reduce<any>((h, card) =>
            Object.assign(h, {
                [card.number]: (h[card.number] || [])
                    .concat(
                        {
                            id: card.id,
                            name: card.name,
                            phone: card.phone,
                            price: card.price,
                        })
            }), {}
        );
    };


    async function fetchApi() {
        return await api.get("getCards", {
            params: {
                firstNumber: feed[0]?.lineCards,
                lastNumber: feed[0]?.lineCards + 200
            }
        }
        ).then((responce) => {
            console.log(JSON.stringify(responce.data));
            setGetList(convertList(responce))
        });
    };


    useEffect(() => {
        let isSubscribed = true
        if (isSubscribed) fetchApi()
        return () => {
            isSubscribed = false
        }
    }, [feed]);


    function LoadPage(value: number | number = 0) {
        const perPage = 84;
        const numbers: NumbersType[] = []

        for (let i = 0; i < perPage; i++) {
            numbers.push({ lineCards: (i * 6) + value, id: String(i) })
        }

        setFeed([...numbers]);
    }

    return { LoadPage, getList }
}
